def champ_recepteur(couches):
    r, saut = 1, 1
    for noyau, stride in couches:
        r += (noyau - 1) * saut
        saut *= stride
    return r, saut

piles = {
    "trois convolutions 3 x 3": [(3, 1), (3, 1), (3, 1)],
    "deux convolutions puis pooling 2 x 2": [(3, 1), (3, 1), (2, 2)],
    "conv, conv, pooling, conv": [(3, 1), (3, 1), (2, 2), (3, 1)],
    "conv dilatée 3 x 3 (d=2) puis conv 3 x 3": [(5, 1), (3, 1)],
}

for nom, couches in piles.items():
    r, saut = champ_recepteur(couches)
    print(f"{nom} : champ {r}, saut {saut}")
